function countPairs(nums) {
  nums.sort((a, b) => a - b);
  const count = new Map();
  let pairs = 0;
  for (const num of nums) {
    const digits = String(num).split('').map(Number);
    const len = digits.length;
    const place = digits.map((_, i) => 10 ** (len - 1 - i));
    const gain = (i, j) => (digits[j] - digits[i]) * (place[i] - place[j]);
    const variants = new Set([num]);
    for (let i = 0; i < len; i++) {
      for (let j = i + 1; j < len; j++) {
        const once = num + gain(i, j);
        variants.add(once);
        [digits[i], digits[j]] = [digits[j], digits[i]];
        for (let p = 0; p < len; p++) {
          for (let q = p + 1; q < len; q++) {
            variants.add(once + gain(p, q));
          }
        }
        [digits[i], digits[j]] = [digits[j], digits[i]];
      }
    }
    for (const value of variants) {
      pairs += count.get(value) ?? 0;
    }
    count.set(num, (count.get(num) ?? 0) + 1);
  }
  return pairs;
}

