function countPairs(nums) {
  // Straight from the definition: the values each number reaches with up to one and up to two swaps of its own digits.
  const swapAll = (texts) => {
    const out = new Set(texts);
    for (const text of texts) {
      for (let i = 0; i < text.length; i++) {
        for (let j = i + 1; j < text.length; j++) {
          const chars = text.split('');
          [chars[i], chars[j]] = [chars[j], chars[i]];
          out.add(chars.join(''));
        }
      }
    }
    return [...out];
  };
  const reach = nums.map(num => {
    const one = swapAll([String(num)]);
    const two = swapAll(one);
    return { one: new Set(one.map(Number)), two: new Set(two.map(Number)) };
  });
  let total = 0;
  for (let a = 0; a < nums.length; a++) {
    for (let b = a + 1; b < nums.length; b++) {
      const x = reach[a], y = reach[b];
      // Two swaps on x, two on y, or one on each.
      if (x.two.has(nums[b]) || y.two.has(nums[a]) || [...x.one].some(v => y.one.has(v))) total++;
    }
  }
  return total;
}

