function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  // 1,000 numbers of up to 7 digits keep a typical solution well inside the time limit.
  const n = large ? 1000 : int(2, 8);
  const digit = () => (rand() < 0.3 ? 0 : int(1, large ? 9 : 4));
  // Every number is one of a few base digit strings after a few random swaps, so many pairs are close.
  const bases = [];
  const baseCount = large ? int(20, 60) : int(1, 3);
  for (let b = 0; b < baseCount; b++) {
    const len = large ? int(4, 7) : int(1, 4);
    const digits = Array.from({ length: len }, digit);
    digits[int(0, len - 1)] = int(1, 9);
    bases.push(digits);
  }
  const nums = [];
  for (let k = 0; k < n; k++) {
    const digits = bases[int(0, baseCount - 1)].slice();
    const swaps = int(0, 3);
    for (let s = 0; s < swaps; s++) {
      const i = int(0, digits.length - 1);
      const j = int(0, digits.length - 1);
      [digits[i], digits[j]] = [digits[j], digits[i]];
    }
    nums.push(Number(digits.join('')));
  }
  return [nums];
}
